"""
支付服务层
"""
from sqlalchemy.orm import Session
from app.models.order import Order
from datetime import datetime


class PaymentService:
    """支付服务类"""

    @staticmethod
    def process_payment(db: Session, order_id: str, payment_method: str = "balance") -> dict:
        """处理支付"""
        db_order = db.query(Order).filter(Order.id == order_id).first()
        if not db_order:
            return {"success": False, "message": "订单不存在"}

        if db_order.status != "pending":
            return {"success": False, "message": "订单状态不允许支付"}

        # 模拟支付处理
        db_order.status = "running"
        db_order.started_at = datetime.utcnow()
        db_order.compute_cost = db_order.selected_quote.get("compute_cost", 0) if db_order.selected_quote else 0
        db_order.energy_cost = db_order.selected_quote.get("energy_cost", 0) if db_order.selected_quote else 0
        db_order.total_cost = db_order.compute_cost + db_order.energy_cost

        db.commit()
        db.refresh(db_order)

        return {"success": True, "order": db_order}

    @staticmethod
    def get_payment_status(db: Session, order_id: str) -> dict:
        """获取支付状态"""
        db_order = db.query(Order).filter(Order.id == order_id).first()
        if not db_order:
            return {"success": False, "message": "订单不存在"}

        return {
            "success": True,
            "status": db_order.status,
            "total_cost": db_order.total_cost,
            "paid_at": db_order.started_at
        }

"""
用户服务层
"""
from sqlalchemy.orm import Session
from app.models.user import User
from app.schemas.user import UserCreate
from datetime import datetime


class UserService:
    """用户服务类"""

    @staticmethod
    def get_user(db: Session, user_id: str) -> User:
        """获取用户"""
        return db.query(User).filter(User.id == user_id).first()

    @staticmethod
    def get_user_by_username(db: Session, username: str) -> User:
        """根据用户名获取用户"""
        return db.query(User).filter(User.username == username).first()

    @staticmethod
    def update_user(db: Session, user_id: str, user_data: dict) -> User:
        """更新用户"""
        db_user = db.query(User).filter(User.id == user_id).first()
        if not db_user:
            return None

        for key, value in user_data.items():
            setattr(db_user, key, value)

        db.commit()
        db.refresh(db_user)

        return db_user

#!/usr/bin/env python3
"""Test backend API endpoints"""
import requests
import json
import sys

BASE = "http://127.0.0.1:8000"

def test_health():
    r = requests.get(f"{BASE}/health")
    print(f"GET /health: {r.status_code} -> {r.json()}")
    return True

def test_login():
    r = requests.post(
        f"{BASE}/api/v1/auth/login",
        json={"username": "testuser", "password": "Test123456"},
    )
    print(f"POST /auth/login: {r.status_code}")
    if r.status_code == 200:
        data = r.json()
        print(f"  token(prefix): {data['access_token'][:20]}...")
        print(f"  user: {data['user']}")
        return data["access_token"]
    else:
        print(f"  ERROR: {r.text}")
        return None

def test_assets(token):
    headers = {"Authorization": f"Bearer {token}"}
    r = requests.get(f"{BASE}/api/v1/assets/", headers=headers, params={"page": 1, "page_size": 5})
    print(f"GET /assets/: {r.status_code}")
    if r.status_code == 200:
        data = r.json()
        print(f"  items: {len(data.get('items', data if isinstance(data, list) else []))}")
        print(f"  total: {data.get('total', 'N/A')}")
    else:
        print(f"  ERROR: {r.text[:500]}")

def test_marketplace():
    r = requests.get(f"{BASE}/api/v1/marketplace/assets", params={"page": 1, "page_size": 5})
    print(f"GET /marketplace/assets: {r.status_code}")
    if r.status_code == 200:
        data = r.json()
        print(f"  items: {len(data.get('items', []))}")
        print(f"  total: {data.get('total', 'N/A')}")
    else:
        print(f"  ERROR: {r.text[:500]}")

def test_quote():
    r = requests.post(
        f"{BASE}/api/v1/scheduling/quote",
        json={"task_type": "inference", "strategy": "cheapest", "estimated_duration_hours": 2.0},
    )
    print(f"POST /scheduling/quote: {r.status_code}")
    if r.status_code == 200:
        data = r.json()
        print(f"  quotes: {len(data.get('quotes', []))}")
        print(f"  recommended: {'YES' if data.get('recommended_quote') else 'NO'}")
    else:
        print(f"  ERROR: {r.text[:500]}")

if __name__ == "__main__":
    try:
        test_health()
    except Exception as e:
        print(f"ERROR: Backend not running? {e}")
        sys.exit(1)

    token = test_login()
    if token:
        test_assets(token)
    test_marketplace()
    test_quote()
    print("\nAll tests completed!")

